export function getCantonById(id: string): Canton | undefined {
  return cantons.find((c) => c.id === id);
}

export function getCantonByAbbreviation(abbr: string): Canton | undefined {
  return cantons.find((c) => c.abbreviation === abbr);
}

export function getCantonIndicatorMeta(id: string): CantonIndicatorMeta | undefined {
  return cantonIndicatorMeta.find((m) => m.id === id);
}
